def ev(k,label,year,sids,support,kind='publication'):
 return dict(id=PRE+k,label=label,kind=kind,track='editions' if kind in ['translation','edition'] else 'contributions',date=dict(year=year,precision='year'),source_ids=['graph:'+s for s in sids],support=support)
def rel(target,text,sids,evidence,kind='contribution'):
 return dict(target=target,relationship=text,source_ids=sids,evidence_note=evidence,relationship_kind=kind)
