write(Path('research-notes.json'),dict(prepared=DAY,baseline_revision=BASE,baseline_sha256=hashlib.sha256((ROOT/'historiography-1920-2000.json').read_bytes()).hexdigest(),scope='Only this owned packet is written; no global apply/build, OpenAlex or shared-file edits.',persons=[dict(person_id=d['pid'],research=d['pid']+'/research-notes.json',life=d['pid']+'/life-status.json') for d in DATA],counts_scope='Queue-supplied dated first-author dissertation counts and exact P: keys are selection witnesses. They are not recomputed by this packet, combined across variants, or substituted for all-authorship totals.',preservation='Original source records are copied into per-person notes for review and unchanged in canonical data; existing collective edges, prose, chronology and field coverage are untouched.',transient_files=[dict(path=str(p.relative_to(HERE)),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),bytes=p.stat().st_size,status='ignored_local_copy') for p in (HERE/'research').glob('*') if p.suffix in ['.pdf','.txt','.html']]))
